    // checkIfFlagCompletion check if we are completing a flag value and return the flag to be completed
    // with its value so far.
    func checkIfFlagCompletion(finalCmd *Command, args []string, lastArg string) (*pflag.Flag, []string, string, error) {
    	if finalCmd.DisableFlagParsing {
    		// DisableFlagParsing=true means that the command itself handles all flags
    		return nil, args, lastArg, nil
    	}

    	var flagName string
    	trimmedArgs := args
    	flagWithEqual := false
    	orgLastArg := lastArg

    	// When doing completion of a flag name, as soon as an argument starts with
    	// a '-' we know it is a flag.  We cannot use isFlagArg() here as it requires
    	// the flag to be complete.
    	if len(lastArg) > 0 && lastArg[0] == '-' {
    		if index := strings.Index(lastArg, "="); index >= 0 {
    			// Flag with an =
    			flagName = strings.TrimLeft(lastArg[:index], "-")
    			lastArg = lastArg[index+1:]
    			flagWithEqual = true
    		} else {
    			// Not finishing with a =, determine if this is a flag or not
    			return nil, trimmedArgs, lastArg, nil
    		}
    	}

    	if len(flagName) == 0 {
    		if len(trimmedArgs) > 0 {
    			prevArg := trimmedArgs[len(trimmedArgs)-1]
    			if isFlagArg(prevArg) {
    				// If the previous arg is a flag, then we are completing its value
    				// Remove the previous flag argument from the list of args
    				trimmedArgs = trimmedArgs[:len(trimmedArgs)-1]

    				// Remove the = sign if present
    				flagName = strings.TrimLeft(prevArg, "-")
    				if index := strings.Index(flagName, "="); index >= 0 {
    					// Last arg already has a value for the flag
    					// e.g., --flag=val
    					// In this case, we don't want to complete the value (it is already set)
    					return nil, args, orgLastArg, nil
    				}
    			}
    		}
    	}

    	if len(flagName) == 0 {
    		// Not completing a flag value
    		return nil, trimmedArgs, lastArg, nil
    	}

    	flag := findFlag(finalCmd, flagName)
    	if flag == nil {
    		// Could be a persistent flag
    		return nil, args, orgLastArg, &flagCompError{subCommand: finalCmd.Name(), flagName: flagName}
    	}

    	if !flagWithEqual {
    		if len(flag.NoOptDefVal) != 0 {
    			// Flag does not require a value, so we're not completing a value for it
    			return nil, trimmedArgs, lastArg, nil
    		}
    	}

    	return flag, trimmedArgs, lastArg, nil
    }

    func findFlag(cmd *Command, name string) *pflag.Flag {
    	flagSet := cmd.Flags()
    	if len(name) == 1 {
    		// Shorthand flag
    		return flagSet.ShorthandLookup(name)
    	}
    	return flagSet.Lookup(name)
    }

    // isFlagArg returns true if the argument looks like a flag.
    func isFlagArg(arg string) bool {
    	return ((len(arg) >= 3 && arg[1] == '-') ||
    		(len(arg) >= 2 && arg[0] == '-' && arg[1] != '-'))
    }

    // nonCompletableFlag returns true if the flag should not be shown in completions
    func nonCompletableFlag(flag *pflag.Flag) bool {
    	return flag.Hidden || len(flag.Deprecated) > 0
    }

